fn dispatch(row: &Value) {
    match row["name"].as_str().unwrap() {
        "Cloid" => check::<Cloid>(row),
        "OidOrCloid" => check::<OidOrCloid>(row),
        "Meta" => check::<Meta>(row),
        "ClearinghouseState" => check::<ClearinghouseState>(row),
        "UserFills" => check::<UserFills>(row),
        "OrderResponse" => check::<OrderResponse>(row),
        "WsTrade" => check::<WsTrade>(row),
        "WsBook" => check::<WsBook>(row),
        "WsLevel" => check::<WsLevel>(row),
        "WsOrder" => check::<WsOrder>(row),
        "WsFill" => check::<WsFill>(row),
        "WsUserFunding" => check::<WsUserFunding>(row),
        "WsLiquidation" => check::<WsLiquidation>(row),
        "WsNonUserCancel" => check::<WsNonUserCancel>(row),
        "SpotClearinghouseState" => check::<SpotClearinghouseState>(row),
        "FrontendOpenOrders" => check::<FrontendOpenOrders>(row),
        "L2Book" => check::<L2Book>(row),
        "CandleSnapshot" => check::<CandleSnapshot>(row),
        "AssetCtx" => check::<AssetCtx>(row),
        "MetaAndAssetCtxs" => check::<MetaAndAssetCtxs>(row),
        "UserFundingDelta" => check::<UserFundingDelta>(row),
        "UserFundingEntry" => check::<UserFundingEntry>(row),
        "UserFunding" => check::<UserFunding>(row),
        "UserNonFundingLedgerDelta" => check::<UserNonFundingLedgerDelta>(row),
        "UserNonFundingLedgerEntry" => check::<UserNonFundingLedgerEntry>(row),
        "UserNonFundingLedgerUpdates" => check::<UserNonFundingLedgerUpdates>(row),
        "FundingHistoryEntry" => check::<FundingHistoryEntry>(row),
        "FundingHistory" => check::<FundingHistory>(row),
        "SpotToken" => check::<SpotToken>(row),
        "SpotMarket" => check::<SpotMarket>(row),
        "SpotMeta" => check::<SpotMeta>(row),
        "SpotAssetCtx" => check::<SpotAssetCtx>(row),
        "SpotMetaAndAssetCtxs" => check::<SpotMetaAndAssetCtxs>(row),
        "UserOpenOrder" => check::<UserOpenOrder>(row),
        "UserOpenOrders" => check::<UserOpenOrders>(row),
        "OrderRequest" => check::<OrderRequest>(row),
        "OrderWire" => check::<OrderWire>(row),
        "CancelOrderRequest" => check::<CancelOrderRequest>(row),
        "CancelByCloidRequest" => check::<CancelByCloidRequest>(row),
        "ModifyRequest" => check::<ModifyRequest>(row),
        "ModifyWire" => check::<ModifyWire>(row),
        "Signature" => check::<Signature>(row),
        "Notification" => check::<Notification>(row),
        "Candle" => check::<Candle>(row),
        "HyperliquidCandle" => check::<HyperliquidCandle>(row),
        "WsUserFill" => check::<WsUserFill>(row),
        "WsUserFills" => check::<WsUserFills>(row),
        "WsUserFundings" => check::<WsUserFundings>(row),
        "WsUserNonFundingLedgerUpdate" => check::<WsUserNonFundingLedgerUpdate>(row),
        "WsUserNonFundingLedgerUpdates" => check::<WsUserNonFundingLedgerUpdates>(row),
        other => panic!("unknown spot root {other}"),
    }
}
